import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import axios from "axios";

const Funds = () => {
  // 1. Balance store karne ke liye state
  const [availableMargin, setAvailableMargin] = useState(0);

  // 2. Database se asli balance mangwane ke liye useEffect
  useEffect(() => {
    const fetchFunds = async () => {
      try {
        const res = await axios.get("http://localhost:8080/userFunds");
        // Maan lete hain aapka backend { margin: 51000 } bhej raha hai
        setAvailableMargin(res.data.margin || 0);
      } catch (err) {
        console.error("Error fetching funds:", err);
      }
    };
    fetchFunds();
  }, []);

  // 3. Add Funds ka logic (Postman ki jagah ab yahan se paisa add hoga)
  const handleAddFunds = async () => {
    const amount = prompt("Kitna paisa add karna chahte hain?");
    if (amount && !isNaN(amount)) {
      try {
        await axios.post("http://localhost:8080/addFunds", { 
          amount: Number(amount) 
        });
        alert(`₹${amount} safaltapurvak add ho gaye!`);
        window.location.reload(); // Turant naya balance dikhane ke liye
      } catch (err) {
        alert("Paisa add karne mein galti hui!");
      }
    }
  };

  return (
    <>
      <div className="funds">
        <p>Instant, zero-cost fund transfers with UPI</p>
        {/* Button par click karne se handleAddFunds chalega */}
        <button className="btn btn-green" onClick={handleAddFunds} style={{cursor: "pointer", border: "none"}}>
          Add funds
        </button>
        <Link className="btn btn-blue">Withdraw</Link>
      </div>

      <div className="row">
        <div className="col">
          <span>
            <p>Equity</p>
          </span>

          <div className="table">
            <div className="data">
              <p>Available margin</p>
              {/* Asli balance yahan dikhega */}
              <p className="imp colored">{availableMargin.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
            </div>
            <div className="data">
              <p>Used margin</p>
              <p className="imp">0.00</p>
            </div>
            <div className="data">
              <p>Available cash</p>
              <p className="imp">{availableMargin.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
            </div>
            <hr />
            <div className="data">
              <p>Opening Balance</p>
              <p>{availableMargin.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
            </div>
            {/* ... Baaki static rows ko waise hi rehne dein ya 0.00 kar dein ... */}
          </div>
        </div>

        <div className="col">
          <div className="commodity">
            <p>You don't have a commodity account</p>
            <Link className="btn btn-blue">Open Account</Link>
          </div>
        </div>
      </div>
    </>
  );
};

export default Funds;
